#!/usr/bin/env python3
"""
ingest_pipeline.py — fail-closed ingestion of repertory + materia medica data.

Philosophy (same as your PRD Rule 8 "No record, no load", made stricter):
  * A row is production-eligible only if it has a registered source, a page, a grade within
    that source's declared scale, a known remedy, a known chapter AND a second person
    (verified_by != entered_by) who checked it against the scan.
  * Anything else goes to the rejected / staged reports. Nothing is guessed or "fixed" silently.
  * No row is ever generated by a language model. LLM/OCR output may *propose* staging rows;
    only human verification promotes them.

Commands
  repertory     staging CSV  -> seed JSON (rubrics + mappings) + reports
  materia       staging CSV  -> materia_medica_symptoms.json + reports
  audit-sample  random sample of staged rows for second-person double-entry checks

Staging CSV columns
  repertory: source_id,page,rubric_path,remedy_abbrev,grade,entered_by,verified_by
  materia  : source_id,page,remedy_abbrev,section,text,entered_by,verified_by
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import json
import random
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

MM_SECTIONS = {
    "mind", "generalities", "modalities", "keynote", "head", "eye", "ear", "nose", "face", "mouth",
    "throat", "stomach", "abdomen", "stool", "urinary", "genitalia", "respiration", "cough", "chest",
    "back", "extremities", "sleep", "fever", "skin", "relationship", "other",
}
MM_MAX_TEXT = 600  # one symptom / one short passage, not whole pages


# ----------------------------------------------------------------------------- helpers
def load_json(path: str | Path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def norm_path(p: str) -> str:
    parts = [re.sub(r"\s+", " ", s).strip() for s in p.split(";")]
    return "; ".join(s for s in parts if s)


def rubric_id(path: str) -> str:
    return "r_" + hashlib.sha1(path.lower().encode("utf-8")).hexdigest()[:12]


def rubric_type(chapter: str) -> str:
    c = chapter.lower()
    return "mental" if c == "mind" else "general" if c == "generalities" else "particular"


def norm_text(t: str) -> str:
    return re.sub(r"\s+", " ", t).strip()


def is_verified(row: dict) -> bool:
    v, e = (row.get("verified_by") or "").strip(), (row.get("entered_by") or "").strip()
    return bool(v) and bool(e) and v.lower() != e.lower()


def read_rows(path: str) -> list[dict]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def load_common(args):
    sources = {s["id"]: s for s in load_json(args.sources)}  # your data_sources.json: list of {id,...}
    cfg = load_json(args.sources_config)
    remedies = {k.strip().lower(): v for k, v in load_json(args.remedies).items()}
    return sources, cfg, remedies


# ----------------------------------------------------------------------------- repertory
def cmd_repertory(args) -> int:
    sources, cfg, remedies = load_common(args)
    chapters = {c.lower(): c for c in load_json(args.chapters)["chapters"]}
    priority: list[str] = cfg.get("merge_priority", [])
    scales: dict = cfg["sources"]

    rejected: list[dict] = []
    staged: list[dict] = []
    good: list[dict] = []

    def reject(row, reason):
        rejected.append({**row, "reject_reason": reason})

    for i, row in enumerate(read_rows(args.input), start=2):  # header is line 1
        row["_line"] = i
        sid = (row.get("source_id") or "").strip()
        if sid not in sources:
            reject(row, "unregistered source_id"); continue
        sc = scales.get(sid)
        if not sc or sc.get("max_grade") in (None, 0):
            reject(row, f"source {sid} has no declared max_grade in sources_config (check the book's legend)"); continue
        if not (row.get("page") or "").strip():
            reject(row, "missing page"); continue
        try:
            raw = int(row["grade"])
        except (ValueError, KeyError):
            reject(row, "grade not an integer"); continue
        if not 1 <= raw <= int(sc["max_grade"]):
            reject(row, f"grade {raw} outside source scale 1..{sc['max_grade']}"); continue
        grade = int(sc.get("grade_map", {}).get(str(raw), raw))
        if not 1 <= grade <= 4:
            reject(row, "mapped grade outside canonical 1..4"); continue
        path = norm_path(row.get("rubric_path") or "")
        if not path:
            reject(row, "empty rubric_path"); continue
        chapter = chapters.get(path.split(";")[0].strip().lower())
        if not chapter:
            reject(row, "first path segment is not a known chapter (see seed/chapters.json)"); continue
        rem = remedies.get((row.get("remedy_abbrev") or "").strip().lower())
        if rem is None:
            reject(row, "unknown remedy_abbrev (add to remedies map after checking the abbreviation key)"); continue

        rec = {"source_id": sid, "page": row["page"].strip(), "chapter": chapter, "path": path,
               "remedy_id": rem, "raw_grade": raw, "grade": grade, "line": i}
        (good if is_verified(row) else staged).append(rec)

    use = good + (staged if args.include_staged else [])

    # ---- merge: one mapping per (rubric, remedy); provenance kept for every source
    grouped: dict[tuple[str, int], list[dict]] = defaultdict(list)
    for r in use:
        grouped[(r["path"], r["remedy_id"])].append(r)

    def prio(sid: str) -> int:
        return priority.index(sid) if sid in priority else len(priority)

    mappings, conflicts = [], []
    for (path, rem), recs in sorted(grouped.items()):
        recs.sort(key=lambda x: (prio(x["source_id"]), x["source_id"], x["page"]))
        chosen = recs[0]
        if len({r["grade"] for r in recs}) > 1:
            conflicts.append({"path": path, "remedy_id": rem,
                              "grades": [{"source_id": r["source_id"], "page": r["page"], "grade": r["grade"]} for r in recs],
                              "chosen": {"source_id": chosen["source_id"], "grade": chosen["grade"]}})
        mappings.append({
            "rubric_id": rubric_id(path), "remedy_id": rem, "grade": chosen["grade"],
            "sources": [{"source_id": r["source_id"], "page": r["page"], "grade": r["grade"]} for r in recs],
        })

    paths = sorted({r["path"] for r in use})
    path_set = set(paths)
    rubrics = []
    for p in paths:
        segs = p.split("; ")
        parent = "; ".join(segs[:-1]) if len(segs) > 1 else None
        rubrics.append({
            "id": rubric_id(p), "path": p, "chapter": segs[0], "depth": len(segs),
            "type": rubric_type(segs[0]),
            "parent_id": rubric_id(parent) if parent and parent in path_set else None,
        })

    out = Path(args.out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "repertory_seed.json").write_text(json.dumps({"rubrics": rubrics, "mappings": mappings}, ensure_ascii=False, indent=1), encoding="utf-8")
    (out / "rejected_rows_report.json").write_text(json.dumps(rejected, ensure_ascii=False, indent=1), encoding="utf-8")
    (out / "grade_conflicts_report.json").write_text(json.dumps(conflicts, ensure_ascii=False, indent=1), encoding="utf-8")
    (out / "staged_unverified_rows.json").write_text(json.dumps(staged, ensure_ascii=False, indent=1), encoding="utf-8")

    reasons = Counter(r["reject_reason"] for r in rejected)
    print(f"rubrics={len(rubrics)} mappings={len(mappings)} verified_rows={len(good)} "
          f"staged_unverified={len(staged)}{' (INCLUDED)' if args.include_staged else ' (excluded)'} rejected={len(rejected)} conflicts={len(conflicts)}")
    for k, v in reasons.most_common():
        print(f"  rejected x{v}: {k}")
    return 1 if (rejected and args.strict) else 0


# ----------------------------------------------------------------------------- materia medica
def cmd_materia(args) -> int:
    sources, cfg, remedies = load_common(args)
    rejected, staged, good = [], [], []
    seen: set[tuple[int, str]] = set()

    for i, row in enumerate(read_rows(args.input), start=2):
        def reject(reason):
            rejected.append({**row, "_line": i, "reject_reason": reason})
        sid = (row.get("source_id") or "").strip()
        if sid not in sources:
            reject("unregistered source_id"); continue
        if not (row.get("page") or "").strip():
            reject("missing page"); continue
        section = (row.get("section") or "").strip().lower()
        if section not in MM_SECTIONS:
            reject(f"section must be one of {sorted(MM_SECTIONS)}"); continue
        text = norm_text(row.get("text") or "")
        if not text or len(text) > MM_MAX_TEXT:
            reject(f"text empty or longer than {MM_MAX_TEXT} chars (one symptom/passage per row)"); continue
        rem = remedies.get((row.get("remedy_abbrev") or "").strip().lower())
        if rem is None:
            reject("unknown remedy_abbrev"); continue
        key = (rem, hashlib.sha1(text.lower().encode()).hexdigest())
        if key in seen:
            reject("duplicate symptom text for this remedy"); continue
        seen.add(key)
        rec = {"remedy_id": rem, "source_id": sid, "page": row["page"].strip(), "section": section, "text": text}
        (good if is_verified(row) else staged).append(rec)

    use = good + (staged if args.include_staged else [])
    out = Path(args.out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "materia_medica_symptoms.json").write_text(json.dumps(use, ensure_ascii=False, indent=1), encoding="utf-8")
    (out / "mm_rejected_rows_report.json").write_text(json.dumps(rejected, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"symptoms={len(use)} verified={len(good)} staged_unverified={len(staged)} rejected={len(rejected)}")
    return 1 if (rejected and args.strict) else 0


# ----------------------------------------------------------------------------- audit sample
def cmd_audit(args) -> int:
    rows = read_rows(args.input)
    rnd = random.Random(args.seed)
    k = max(1, int(len(rows) * args.rate)) if rows else 0
    sample = rnd.sample(rows, k) if k else []
    fields = list(rows[0].keys()) + ["audit_result", "auditor", "correction"] if rows else []
    with open(args.output, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for r in sample:
            w.writerow({**r, "audit_result": "", "auditor": "", "correction": ""})
    print(f"wrote {len(sample)} of {len(rows)} rows to {args.output} (seed={args.seed}). "
          "Auditor compares each row with the scan; error rate > 1% => re-verify the whole batch.")
    return 0


# ----------------------------------------------------------------------------- cli
def main(argv=None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = p.add_subparsers(dest="cmd", required=True)

    def common(sp):
        sp.add_argument("--input", required=True)
        sp.add_argument("--sources", default="seed/data_sources.json")
        sp.add_argument("--sources-config", default="seed/sources_config.json")
        sp.add_argument("--remedies", default="seed/remedies_map.json", help='JSON {"abbrev": remedy_id}')
        sp.add_argument("--out-dir", default="seed/build")
        sp.add_argument("--include-staged", action="store_true", help="include rows without independent verification (dev only)")
        sp.add_argument("--strict", action="store_true", help="exit 1 if any row is rejected")

    r = sub.add_parser("repertory"); common(r); r.add_argument("--chapters", default="seed/chapters.json"); r.set_defaults(fn=cmd_repertory)
    m = sub.add_parser("materia"); common(m); m.set_defaults(fn=cmd_materia)
    a = sub.add_parser("audit-sample")
    a.add_argument("--input", required=True); a.add_argument("--output", required=True)
    a.add_argument("--rate", type=float, default=0.05); a.add_argument("--seed", type=int, default=42)
    a.set_defaults(fn=cmd_audit)

    args = p.parse_args(argv)
    return args.fn(args)


if __name__ == "__main__":
    sys.exit(main())
